    "question": "How can someone else rerun an analysis and understand its limits?",
    "is_question": true,
    "form": "Analysis notebook: Question, Context, Workflow, Sensitivity checks, Practical exercises, Summary and reuse.",
    "object": "One persistent open notebook made of six thick leaves.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The story connects Mira’s specific workflow and sensitivity contributions, retrospective association, and bounded practical teaching role."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The leaves explain workflow sequence, assumption comparisons and the connection to exercises through spatial rearrangement."
    },
    "depth": {
      "result": "pass",
      "reason": "The notebook moves from identity and contribution through workflow, checks and teaching to an evidence-based handoff."
    },
    "clipart": {
      "result": "pass",
      "reason": "The notebook is a confirmed working artifact whose contents and transformations carry the story, rather than a stock scientific emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan preserves candidacy, preprint status, contribution boundaries, association-level evidence and the personal teaching count."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first screen specifies name, role, contribution, proof links, CV and email without requiring the full scroll."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The guiding question uses ordinary language, and the plan explains sensitivity checks while preserving scientifically accurate limits."
    }
  },
